<?php
require_once 'app_bootstrap.php';require_once 'db.php';require_once 'security.php';require_once 'notifications.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in.');
if($_SERVER['REQUEST_METHOD']!=='POST')redirect_with_message('my-bookings.php','Use the review form.');
verify_csrf();
$bookingId=filter_input(INPUT_POST,'booking_id',FILTER_VALIDATE_INT)?:0;$packageRating=(int)($_POST['package_rating']??0);$hotelRating=(int)($_POST['hotel_rating']??0);$text=trim($_POST['review_text']??'');
if(!in_array($packageRating,[1,2,3,4,5],true)||!in_array($hotelRating,[1,2,3,4,5],true)||strlen($text)>1000)redirect_with_message('booking-review.php?booking_id='.$bookingId,'Choose valid ratings from 1 to 5.');
try{$db=db_connect();ensure_app_schema($db);$db->begin_transaction();$booking=$db->execute_query("SELECT id,user_email,package_id,hotel_id,status,booking_reference FROM bookings WHERE id=? AND user_email=? FOR UPDATE",[$bookingId,$_SESSION['user_email']])->fetch_assoc();if(!$booking)throw new RuntimeException('Booking not found.');if($booking['status']!=='completed')throw new RuntimeException('Reviews open after completion.');if(!$booking['package_id'])throw new RuntimeException('Package information is missing.');if($db->execute_query('SELECT id FROM booking_reviews WHERE booking_id=?',[$bookingId])->fetch_assoc())throw new RuntimeException('A review already exists for this booking.');$ok=$db->execute_query("INSERT INTO booking_reviews(booking_id,user_email,package_id,hotel_id,package_rating,hotel_rating,review_text,status) VALUES(?,?,?,?,?,?,?,'published')",[$bookingId,$_SESSION['user_email'],(int)$booking['package_id'],$booking['hotel_id']?(int)$booking['hotel_id']:null,$packageRating,$hotelRating,$text]);if(!$ok)throw new RuntimeException('Review could not be saved.');create_notification($db,'Review received','Thanks for reviewing booking '.($booking['booking_reference']?:'#'.$bookingId).'.','user',$_SESSION['user_email'],'my-bookings.php#booking-'.$bookingId,'success');$db->commit();redirect_with_message('my-bookings.php#booking-'.$bookingId,'Thank you. Your review was submitted.');}catch(Throwable $error){if(isset($db)){try{$db->rollback();}catch(Throwable $ignored){}}redirect_with_message('booking-review.php?booking_id='.$bookingId,$error->getMessage());}
